{"refs":["alphabet","length","modulus","residue","sum_min","sum_max","target_digit","target_count"],"code":"from itertools import product

def solve(facts):
    alphabet = sorted(set(facts['alphabet']))
    n = facts['length']
    m = facts['modulus']
    residue = facts['residue']
    lo, hi = facts['sum_min'], facts['sum_max']
    target, required = facts['target_digit'], facts['target_count']
    states = {(None, 0, 0, 0): 1}
    for position in range(n):
        following = {}
        remaining = n - position - 1
        for (previous, remainder, total, copies), ways in states.items():
            for digit in alphabet:
                if digit == previous:
                    continue
                new_total = total + digit
                new_copies = copies + int(digit == target)
                if new_total > hi or new_copies > required or new_copies + remaining < required:
                    continue
                key = (digit, (10 * remainder + digit) % m, new_total, new_copies)
                following[key] = following.get(key, 0) + ways
        states = following
    count = 0
    digit_sum_total = 0
    for (previous, remainder, total, copies), ways in states.items():
        if remainder == residue and lo <= total <= hi and copies == required:
            count += ways
            digit_sum_total += total * ways
    return {'count': count, 'digit_sum_total': digit_sum_total}

def check(answer, facts):
    alphabet = sorted(set(facts['alphabet']))
    n = facts['length']
    weights = [10 ** (n - 1 - i) for i in range(n)]
    count = 0
    digit_sum_total = 0
    for digits in product(alphabet, repeat=n):
        if any(digits[i] == digits[i + 1] for i in range(n - 1)):
            continue
        if sum(digit == facts['target_digit'] for digit in digits) != facts['target_count']:
            continue
        total = sum(digits)
        if not facts['sum_min'] <= total <= facts['sum_max']:
            continue
        value = sum(digit * weight for digit, weight in zip(digits, weights))
        if value % facts['modulus'] != facts['residue']:
            continue
        count += 1
        digit_sum_total += total
    return answer == {'count': count, 'digit_sum_total': digit_sum_total}
